문 10. 다음 C 언어 프로그램의 출력 결과는?
#include <stdio.h>
#define SWAP(x, y, t) ((t)=(x), (x)=(y), (y)=(t))
void recursive(char *list, int i, int n) {
int j, temp;
if (i == n) {
for (j = 0 ; j <= n ; j++)
printf("%c", list[j]);
printf(" ");
}
else {
for (j = i ; j <= n ; j++) {
SWAP(list[i], list[j], temp);
recursive(list, i + 1, n);
SWAP(list[i], list[j], temp);
}
}
}
int main()
{
char list[3] = {'a', 'b', 'c'};
recursive(list, 0, 2);
}

